module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiRange, EuiSpacer } from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      value: '120',\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiRange\n          id={makeId()}\n          min={100}\n          max={200}\n          step={0.05}\n          value={this.state.value}\n          onChange={this.onChange}\n          showLabels\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiRange\n          id={makeId()}\n          min={100}\n          max={200}\n          value={this.state.value}\n          onChange={this.onChange}\n          showLabels\n          showValue\n        />\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiRange\n          id={makeId()}\n          min={100}\n          max={200}\n          value={this.state.value}\n          onChange={this.onChange}\n          showLabels\n          showRange\n          showValue\n          valuePrepend=\"100 - \"\n        />\n      </Fragment>\n    );\n  }\n}\n"