module.exports = "import React, { Component, Fragment } from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiButtonIcon,\n  EuiHealth,\n  EuiButton,\n  EuiDescriptionList,\n} from '../../../../../src/components';\n\nimport { RIGHT_ALIGNMENT } from '../../../../../src/services';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      pageIndex: 0,\n      pageSize: 5,\n      sortField: 'firstName',\n      sortDirection: 'asc',\n      selectedItems: [],\n      itemIdToExpandedRowMap: {},\n    };\n  }\n\n  onTableChange = ({ page = {}, sort = {} }) => {\n    const { index: pageIndex, size: pageSize } = page;\n\n    const { field: sortField, direction: sortDirection } = sort;\n\n    this.setState({\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n    });\n  };\n\n  onSelectionChange = selectedItems => {\n    this.setState({ selectedItems });\n  };\n\n  onClickDelete = () => {\n    const { selectedItems } = this.state;\n    store.deleteUsers(...selectedItems.map(user => user.id));\n\n    this.setState({\n      selectedItems: [],\n    });\n  };\n\n  renderDeleteButton() {\n    const { selectedItems } = this.state;\n\n    if (selectedItems.length === 0) {\n      return;\n    }\n\n    return (\n      <EuiButton color=\"danger\" iconType=\"trash\" onClick={this.onClickDelete}>\n        Delete {selectedItems.length} Users\n      </EuiButton>\n    );\n  }\n\n  toggleDetails = item => {\n    const itemIdToExpandedRowMap = { ...this.state.itemIdToExpandedRowMap };\n    if (itemIdToExpandedRowMap[item.id]) {\n      delete itemIdToExpandedRowMap[item.id];\n    } else {\n      const { nationality, online } = item;\n      const country = store.getCountry(nationality);\n      const color = online ? 'success' : 'danger';\n      const label = online ? 'Online' : 'Offline';\n      const listItems = [\n        {\n          title: 'Nationality',\n          description: `${country.flag} ${country.name}`,\n        },\n        {\n          title: 'Online',\n          description: <EuiHealth color={color}>{label}</EuiHealth>,\n        },\n      ];\n      itemIdToExpandedRowMap[item.id] = (\n        <EuiDescriptionList listItems={listItems} />\n      );\n    }\n    this.setState({ itemIdToExpandedRowMap });\n  };\n\n  render() {\n    const {\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection,\n      itemIdToExpandedRowMap,\n    } = this.state;\n\n    const { pageOfItems, totalItemCount } = store.findUsers(\n      pageIndex,\n      pageSize,\n      sortField,\n      sortDirection\n    );\n\n    const deleteButton = this.renderDeleteButton();\n\n    const columns = [\n      {\n        field: 'firstName',\n        name: 'First Name',\n        sortable: true,\n        truncateText: true,\n        mobileOptions: {\n          render: item => (\n            <span>\n              {item.firstName} {item.lastName}\n            </span>\n          ),\n          header: false,\n          truncateText: false,\n          enlarge: true,\n          fullWidth: true,\n        },\n      },\n      {\n        field: 'lastName',\n        name: 'Last Name',\n        truncateText: true,\n        mobileOptions: {\n          show: false,\n        },\n      },\n      {\n        field: 'dateOfBirth',\n        name: 'Date of Birth',\n        dataType: 'date',\n        render: date => formatDate(date, 'dobLong'),\n        sortable: true,\n      },\n      {\n        name: 'Actions',\n        actions: [\n          {\n            name: 'Clone',\n            description: 'Clone this person',\n            type: 'icon',\n            icon: 'copy',\n            onClick: () => '',\n          },\n        ],\n      },\n      {\n        align: RIGHT_ALIGNMENT,\n        width: '40px',\n        isExpander: true,\n        render: item => (\n          <EuiButtonIcon\n            onClick={() => this.toggleDetails(item)}\n            aria-label={itemIdToExpandedRowMap[item.id] ? 'Collapse' : 'Expand'}\n            iconType={itemIdToExpandedRowMap[item.id] ? 'arrowUp' : 'arrowDown'}\n          />\n        ),\n      },\n    ];\n\n    const pagination = {\n      pageIndex: pageIndex,\n      pageSize: pageSize,\n      totalItemCount: totalItemCount,\n      pageSizeOptions: [3, 5, 8],\n    };\n\n    const sorting = {\n      sort: {\n        field: sortField,\n        direction: sortDirection,\n      },\n    };\n\n    const selection = {\n      selectable: user => user.online,\n      selectableMessage: selectable =>\n        !selectable ? 'User is currently offline' : undefined,\n      onSelectionChange: this.onSelectionChange,\n    };\n\n    return (\n      <Fragment>\n        {deleteButton}\n        <EuiBasicTable\n          items={pageOfItems}\n          itemId=\"id\"\n          itemIdToExpandedRowMap={this.state.itemIdToExpandedRowMap}\n          isExpandable={true}\n          hasActions={true}\n          columns={columns}\n          pagination={pagination}\n          sorting={sorting}\n          isSelectable={true}\n          selection={selection}\n          onChange={this.onTableChange}\n        />\n      </Fragment>\n    );\n  }\n}\n"