module.exports = "import React, { Component } from 'react';\nimport { formatDate } from '../../../../../src/services/format';\nimport { createDataStore } from '../data_store';\n\nimport {\n  EuiBasicTable,\n  EuiCode,\n  EuiLink,\n  EuiHealth,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiSpacer,\n  EuiSwitch,\n} from '../../../../../src/components';\n\n/*\nExample user object:\n\n{\n  id: '1',\n  firstName: 'john',\n  lastName: 'doe',\n  github: 'johndoe',\n  dateOfBirth: Date.now(),\n  nationality: 'NL',\n  online: true\n}\n\nExample country object:\n\n{\n  code: 'NL',\n  name: 'Netherlands',\n  flag: '🇳🇱'\n}\n*/\n\nconst store = createDataStore();\n\nexport class Table extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      pageIndex: 0,\n      pageSize: 5,\n      showPerPageOptions: true,\n    };\n  }\n\n  onTableChange = ({ page = {} }) => {\n    const { index: pageIndex, size: pageSize } = page;\n\n    this.setState({\n      pageIndex,\n      pageSize,\n    });\n  };\n\n  renderStatus = online => {\n    const color = online ? 'success' : 'danger';\n    const label = online ? 'Online' : 'Offline';\n    return <EuiHealth color={color}>{label}</EuiHealth>;\n  };\n\n  togglePerPageOptions = () =>\n    this.setState(state => ({ showPerPageOptions: !state.showPerPageOptions }));\n\n  render() {\n    const { pageIndex, pageSize, showPerPageOptions } = this.state;\n\n    const { pageOfItems, totalItemCount } = store.findUsers(\n      pageIndex,\n      pageSize\n    );\n\n    const columns = [\n      {\n        field: 'firstName',\n        name: 'First Name',\n        truncateText: true,\n        hideForMobile: true,\n        mobileOptions: {\n          show: false,\n        },\n      },\n      {\n        field: 'lastName',\n        name: 'Last Name',\n        truncateText: true,\n        mobileOptions: {\n          show: false,\n        },\n      },\n      {\n        field: 'firstName',\n        name: 'Full Name',\n        mobileOptions: {\n          header: false,\n          only: true,\n          enlarge: true,\n          fullWidth: true,\n        },\n        render: (name, item) => (\n          <EuiFlexGroup responsive={false} alignItems=\"center\">\n            <EuiFlexItem>\n              {item.firstName} {item.lastName}\n            </EuiFlexItem>\n            <EuiFlexItem grow={false}>\n              {this.renderStatus(item.online)}\n            </EuiFlexItem>\n          </EuiFlexGroup>\n        ),\n      },\n      {\n        field: 'github',\n        name: 'Github',\n        render: username => (\n          <EuiLink href={`https://github.com/${username}`} target=\"_blank\">\n            {username}\n          </EuiLink>\n        ),\n      },\n      {\n        field: 'dateOfBirth',\n        name: 'Date of Birth',\n        dataType: 'date',\n        render: date => formatDate(date, 'dobLong'),\n      },\n      {\n        field: 'nationality',\n        name: 'Nationality',\n        render: countryCode => {\n          const country = store.getCountry(countryCode);\n          return `${country.flag} ${country.name}`;\n        },\n      },\n      {\n        field: 'online',\n        name: 'Online',\n        dataType: 'boolean',\n        render: online => this.renderStatus(online),\n      },\n    ];\n\n    const pagination = {\n      pageIndex,\n      pageSize,\n      totalItemCount,\n      pageSizeOptions: [3, 5, 8],\n      hidePerPageOptions: !showPerPageOptions,\n    };\n\n    return (\n      <div>\n        <EuiSwitch\n          label={\n            <span>\n              Hide per page options with{' '}\n              <EuiCode>pagination.hidePerPageOptions = true</EuiCode>\n            </span>\n          }\n          onChange={this.togglePerPageOptions}\n        />\n        <EuiSpacer size=\"xl\" />\n        <EuiBasicTable\n          items={pageOfItems}\n          columns={columns}\n          pagination={pagination}\n          onChange={this.onTableChange}\n        />\n      </div>\n    );\n  }\n}\n"