module.exports = "import React, { Fragment } from 'react';\n\nimport {\n  EuiFormControlLayoutDelimited,\n  EuiSpacer,\n  EuiFormLabel,\n  EuiIcon,\n} from '../../../../src/components';\n\nexport default () => (\n  <Fragment>\n    <EuiFormControlLayoutDelimited\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n    <EuiFormControlLayoutDelimited\n      append={<EuiFormLabel>px</EuiFormLabel>}\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n    <EuiFormControlLayoutDelimited\n      icon=\"vector\"\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n    <EuiFormControlLayoutDelimited\n      clear={{ onClick: () => {} }}\n      isLoading\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n    <EuiFormControlLayoutDelimited\n      fullWidth\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n    <EuiFormControlLayoutDelimited\n      isLoading\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n    <EuiFormControlLayoutDelimited\n      compressed\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n\n    <EuiFormControlLayoutDelimited\n      prepend={<EuiFormLabel>Add</EuiFormLabel>}\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      delimiter=\"+\"\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n\n    <EuiFormControlLayoutDelimited\n      prepend={<EuiFormLabel>Merge</EuiFormLabel>}\n      startControl={\n        <input type=\"number\" placeholder=\"0\" className=\"euiFieldNumber\" />\n      }\n      delimiter={<EuiIcon type=\"merge\" />}\n      endControl={\n        <input type=\"number\" placeholder=\"100\" className=\"euiFieldNumber\" />\n      }\n    />\n\n    <EuiSpacer size=\"m\" />\n\n    <EuiFormControlLayoutDelimited\n      readOnly\n      prepend={<EuiFormLabel>Read only</EuiFormLabel>}\n      startControl={\n        <input\n          type=\"number\"\n          placeholder=\"0\"\n          className=\"euiFieldNumber\"\n          readOnly\n        />\n      }\n      endControl={\n        <input\n          type=\"number\"\n          placeholder=\"100\"\n          className=\"euiFieldNumber\"\n          readOnly\n        />\n      }\n    />\n  </Fragment>\n);\n"