module.exports = "import React, { Component, Fragment } from 'react';\nimport { DisplayToggles } from './display_toggles';\n\nimport {\n  EuiFilePicker,\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiText,\n  EuiSpacer,\n  EuiSwitch,\n} from '../../../../src/components';\n\nexport class FilePicker extends Component {\n  constructor(props) {\n    super(props);\n    this.state = {\n      files: {},\n      large: true,\n    };\n  }\n\n  onChange = files => {\n    this.setState({\n      files: files,\n    });\n  };\n\n  renderFiles() {\n    if (this.state.files.length > 0) {\n      return (\n        <ul>\n          {Object.keys(this.state.files).map((item, i) => (\n            <li key={i}>\n              <strong>{this.state.files[item].name}</strong> (\n              {this.state.files[item].size} bytes)\n            </li>\n          ))}\n        </ul>\n      );\n    } else {\n      return (\n        <p>Add some files to see a demo of retrieving from the FileList</p>\n      );\n    }\n  }\n\n  render() {\n    return (\n      <Fragment>\n        <EuiFlexGroup>\n          <EuiFlexItem grow={2}>\n            {/* DisplayToggles wrapper for Docs only */}\n            <DisplayToggles\n              canReadOnly={false}\n              extras={[\n                <EuiSwitch\n                  label={'large'}\n                  checked={this.state.large}\n                  onChange={e => {\n                    this.setState({ large: e.target.checked });\n                  }}\n                />,\n              ]}>\n              <EuiFilePicker\n                id=\"asdf2\"\n                multiple\n                initialPromptText=\"Select or drag and drop multiple files\"\n                onChange={files => {\n                  this.onChange(files);\n                }}\n                display={this.state.large ? 'large' : 'default'}\n              />\n            </DisplayToggles>\n            <EuiSpacer />\n          </EuiFlexItem>\n          <EuiFlexItem>\n            <EuiText>\n              <h3>Files attached</h3>\n              {this.renderFiles()}\n            </EuiText>\n          </EuiFlexItem>\n        </EuiFlexGroup>\n      </Fragment>\n    );\n  }\n}\n"