module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButton,\n  EuiCheckboxGroup,\n  EuiFieldText,\n  EuiForm,\n  EuiFormRow,\n  EuiFilePicker,\n  EuiLink,\n  EuiRange,\n  EuiSelect,\n  EuiSpacer,\n  EuiSwitch,\n  EuiText,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    const idPrefix = makeId();\n\n    this.state = {\n      isSwitchChecked: false,\n      checkboxes: [\n        {\n          id: `${idPrefix}0`,\n          label: 'Option one',\n        },\n        {\n          id: `${idPrefix}1`,\n          label: 'Option two is checked by default',\n        },\n        {\n          id: `${idPrefix}2`,\n          label: 'Option three',\n        },\n      ],\n      checkboxIdToSelectedMap: {\n        [`${idPrefix}1`]: true,\n      },\n      radios: [\n        {\n          id: `${idPrefix}4`,\n          label: 'Option one',\n        },\n        {\n          id: `${idPrefix}5`,\n          label: 'Option two is selected by default',\n        },\n        {\n          id: `${idPrefix}6`,\n          label: 'Option three',\n        },\n      ],\n      radioIdSelected: `${idPrefix}5`,\n    };\n  }\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  };\n\n  onCheckboxChange = optionId => {\n    const newCheckboxIdToSelectedMap = {\n      ...this.state.checkboxIdToSelectedMap,\n      ...{\n        [optionId]: !this.state.checkboxIdToSelectedMap[optionId],\n      },\n    };\n\n    this.setState({\n      checkboxIdToSelectedMap: newCheckboxIdToSelectedMap,\n    });\n  };\n\n  onRadioChange = optionId => {\n    this.setState({\n      radioIdSelected: optionId,\n    });\n  };\n\n  render() {\n    return (\n      <EuiForm>\n        <EuiFormRow label=\"Text field\" helpText=\"I am some friendly help text.\">\n          <EuiFieldText name=\"first\" />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"Select (with no initial selection)\"\n          labelAppend={\n            <EuiText size=\"xs\">\n              <EuiLink>Link to some help</EuiLink>\n            </EuiText>\n          }>\n          <EuiSelect\n            hasNoInitialSelection\n            options={[\n              { value: 'option_one', text: 'Option one' },\n              { value: 'option_two', text: 'Option two' },\n              { value: 'option_three', text: 'Option three' },\n            ]}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"File picker\">\n          <EuiFilePicker />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Range\">\n          <EuiRange min={0} max={100} name=\"range\" id=\"range\" />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Use a switch instead of a single checkbox\">\n          <EuiSwitch\n            name=\"switch\"\n            label=\"Should we do this?\"\n            checked={this.state.isSwitchChecked}\n            onChange={this.onSwitchChange}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow\n          label=\"Checkbox group labels should use a `legend` label type\"\n          labelType=\"legend\">\n          <EuiCheckboxGroup\n            options={this.state.checkboxes}\n            idToSelectedMap={this.state.checkboxIdToSelectedMap}\n            onChange={this.onCheckboxChange}\n          />\n        </EuiFormRow>\n\n        <EuiSpacer />\n\n        <EuiButton type=\"submit\" fill>\n          Save form\n        </EuiButton>\n      </EuiForm>\n    );\n  }\n}\n"