module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiCheckboxGroup,\n  EuiComboBox,\n  EuiFieldText,\n  EuiFormRow,\n  EuiFilePicker,\n  EuiRange,\n  EuiSelect,\n  EuiSwitch,\n  EuiPanel,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    const idPrefix = makeId();\n\n    this.state = {\n      isSwitchChecked: false,\n      checkboxes: [\n        {\n          id: `${idPrefix}0`,\n          label: 'Option one',\n        },\n        {\n          id: `${idPrefix}1`,\n          label: 'Option two is checked by default',\n        },\n        {\n          id: `${idPrefix}2`,\n          label: 'Option three',\n        },\n      ],\n      checkboxIdToSelectedMap: {\n        [`${idPrefix}1`]: true,\n      },\n      comboBoxSelectionOptions: [],\n      value: '20',\n    };\n  }\n\n  onRangeChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  onSwitchChange = () => {\n    this.setState({\n      isSwitchChecked: !this.state.isSwitchChecked,\n    });\n  };\n\n  onCheckboxChange = optionId => {\n    const newCheckboxIdToSelectedMap = {\n      ...this.state.checkboxIdToSelectedMap,\n      ...{\n        [optionId]: !this.state.checkboxIdToSelectedMap[optionId],\n      },\n    };\n\n    this.setState({\n      checkboxIdToSelectedMap: newCheckboxIdToSelectedMap,\n    });\n  };\n\n  render() {\n    return (\n      <EuiPanel style={{ maxWidth: 300 }}>\n        <EuiFormRow\n          label=\"Text field\"\n          helpText=\"I am some friendly help text.\"\n          display=\"rowCompressed\">\n          <EuiFieldText name=\"first\" isLoading compressed />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Select\" display=\"rowCompressed\">\n          <EuiSelect\n            options={[\n              { value: 'option_one', text: 'Option one' },\n              { value: 'option_two', text: 'Option two' },\n              { value: 'option_three', text: 'Option three' },\n            ]}\n            compressed\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"File picker\" display=\"rowCompressed\">\n          <EuiFilePicker compressed display=\"default\" />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Combobox\" display=\"rowCompressed\">\n          <EuiComboBox\n            options={[\n              { label: 'Option one' },\n              { label: 'Option two' },\n              { label: 'Option three' },\n            ]}\n            compressed\n            selectedOptions={this.state.comboBoxSelectionOptions}\n            onChange={comboBoxSelectionOptions =>\n              this.setState({ comboBoxSelectionOptions })\n            }\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Range\" display=\"rowCompressed\">\n          <EuiRange\n            min={0}\n            max={100}\n            name=\"range\"\n            id=\"range\"\n            showInput\n            compressed\n            value={this.state.value}\n            onChange={this.onRangeChange}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Switch\" display=\"rowCompressed\">\n          <EuiSwitch\n            label=\"Should we do this?\"\n            name=\"switch\"\n            checked={this.state.isSwitchChecked}\n            onChange={this.onSwitchChange}\n          />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Checkboxes\" display=\"rowCompressed\">\n          <EuiCheckboxGroup\n            options={this.state.checkboxes}\n            idToSelectedMap={this.state.checkboxIdToSelectedMap}\n            onChange={this.onCheckboxChange}\n            compressed\n          />\n        </EuiFormRow>\n      </EuiPanel>\n    );\n  }\n}\n"