module.exports = "import React from 'react';\n\nimport {\n  EuiFlexGroup,\n  EuiFlexItem,\n  EuiFormRow,\n  EuiButton,\n  EuiFieldText,\n  EuiFieldNumber,\n  EuiAvatar,\n} from '../../../../src/components/';\n\nexport default () => (\n  <EuiFlexGroup style={{ maxWidth: 600 }}>\n    <EuiFlexItem grow={false} style={{ width: 100 }}>\n      <EuiFormRow label=\"Age\">\n        <EuiFieldNumber max={10} placeholder={42} />\n      </EuiFormRow>\n    </EuiFlexItem>\n    <EuiFlexItem>\n      <EuiFormRow label=\"Full name\">\n        <EuiFieldText icon=\"user\" placeholder=\"John Doe\" />\n      </EuiFormRow>\n    </EuiFlexItem>\n    <EuiFlexItem grow={false}>\n      <EuiFormRow label=\"Avatar\" display=\"center\">\n        <EuiAvatar name=\"John Doe\" size=\"s\" />\n      </EuiFormRow>\n    </EuiFlexItem>\n    <EuiFlexItem grow={false}>\n      <EuiFormRow hasEmptyLabelSpace display=\"center\">\n        <EuiButton>Save</EuiButton>\n      </EuiFormRow>\n    </EuiFlexItem>\n  </EuiFlexGroup>\n);\n"