module.exports = "import React, { Component, Fragment } from 'react';\n\nimport { EuiRadioGroup, EuiSpacer, EuiTitle } from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    const idPrefix = makeId();\n\n    this.radios = [\n      {\n        id: `${idPrefix}0`,\n        label: 'Option one',\n      },\n      {\n        id: `${idPrefix}1`,\n        label: 'Option two is checked by default',\n      },\n      {\n        id: `${idPrefix}2`,\n        label: 'Option three',\n        disabled: true,\n      },\n    ];\n\n    this.state = {\n      radioIdSelected: `${idPrefix}1`,\n    };\n  }\n\n  onChange = optionId => {\n    this.setState({\n      radioIdSelected: optionId,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiRadioGroup\n          options={this.radios}\n          idSelected={this.state.radioIdSelected}\n          onChange={this.onChange}\n        />\n\n        <EuiSpacer size=\"m\" />\n\n        <EuiTitle size=\"xxs\">\n          <h3>Disabled</h3>\n        </EuiTitle>\n\n        <EuiSpacer size=\"s\" />\n\n        <EuiRadioGroup\n          options={this.radios}\n          idSelected={this.state.radioIdSelected}\n          onChange={this.onChange}\n          disabled\n        />\n      </Fragment>\n    );\n  }\n}\n"