module.exports = "import React, { Component, Fragment } from 'react';\nimport { orderBy } from 'lodash';\nimport {\n  EuiButton,\n  EuiCode,\n  EuiFlyout,\n  EuiFlyoutFooter,\n  EuiFlyoutHeader,\n  EuiPopover,\n  EuiPopoverFooter,\n  EuiPopoverTitle,\n  EuiSelectable,\n  EuiSpacer,\n  EuiTitle,\n} from '../../../../src/components';\n\nimport { Options } from './data';\nimport { createDataStore } from '../tables/data_store';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.countries = createDataStore().countries.map(country => {\n      return {\n        id: country.code,\n        label: `${country.name}`,\n        append: country.flag,\n      };\n    });\n\n    this.state = {\n      options: Options,\n      countries: this.countries,\n      isPopoverOpen: false,\n      isFlyoutVisible: false,\n    };\n  }\n\n  onButtonClick = () => {\n    this.setState(prevState => ({\n      options: orderBy(prevState.options, ['checked'], ['asc']),\n      isPopoverOpen: !prevState.isPopoverOpen,\n    }));\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  onChange = options => {\n    this.setState({\n      options,\n    });\n  };\n\n  onFlyoutChange = options => {\n    this.setState({\n      countries: options,\n    });\n  };\n\n  closeFlyout = () => {\n    this.setState({ isFlyoutVisible: false });\n  };\n\n  showFlyout = () => {\n    this.setState({ isFlyoutVisible: true });\n  };\n\n  render() {\n    const { isPopoverOpen, options, countries } = this.state;\n\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick.bind(this)}>\n        Show popover\n      </EuiButton>\n    );\n\n    return (\n      <Fragment>\n        <EuiPopover\n          id=\"popover\"\n          panelPaddingSize=\"none\"\n          button={button}\n          isOpen={isPopoverOpen}\n          closePopover={this.closePopover}>\n          <EuiSelectable\n            searchable\n            searchProps={{\n              placeholder: 'Filter list',\n              compressed: true,\n            }}\n            options={options}\n            onChange={this.onChange}>\n            {(list, search) => (\n              <div style={{ width: 240 }}>\n                <EuiPopoverTitle>{search}</EuiPopoverTitle>\n                {list}\n                <EuiPopoverFooter>\n                  <EuiButton size=\"s\" fullWidth>\n                    Manage this list\n                  </EuiButton>\n                </EuiPopoverFooter>\n              </div>\n            )}\n          </EuiSelectable>\n        </EuiPopover>\n\n        <EuiSpacer />\n\n        <EuiButton onClick={this.showFlyout}>Show flyout</EuiButton>\n\n        {this.state.isFlyoutVisible && (\n          <EuiFlyout\n            ownFocus\n            onClose={this.closeFlyout}\n            aria-labelledby=\"flyoutTitle\">\n            <EuiSelectable\n              searchable\n              options={countries}\n              onChange={this.onFlyoutChange}\n              height=\"full\">\n              {(list, search) => (\n                <Fragment>\n                  <EuiFlyoutHeader hasBorder>\n                    <EuiTitle size=\"m\">\n                      <h2 id=\"flyoutTitle\">Be mindful of the flexbox</h2>\n                    </EuiTitle>\n                    <EuiSpacer />\n                    {search}\n                  </EuiFlyoutHeader>\n                  <EuiSpacer size=\"xs\" />\n                  {list}\n                </Fragment>\n              )}\n            </EuiSelectable>\n            <EuiSpacer size=\"xs\" />\n            <EuiFlyoutFooter>\n              <EuiButton fill>Some extra action</EuiButton>\n            </EuiFlyoutFooter>\n          </EuiFlyout>\n        )}\n\n        <EuiSpacer />\n\n        <EuiTitle size=\"xxs\">\n          <h4>\n            Using <EuiCode>listProps.bordered = true</EuiCode>\n          </h4>\n        </EuiTitle>\n\n        <EuiSpacer />\n\n        <EuiSelectable\n          options={options}\n          onChange={() => {}}\n          style={{ width: 300 }}\n          listProps={{ bordered: true }}>\n          {list => list}\n        </EuiSelectable>\n      </Fragment>\n    );\n  }\n}\n"